// ПЛК-локации для elevator_mini.lam
//
// Внешняя карта адресов (фича 0020) для цели st-at: держит ПЛК-локации
// ОТДЕЛЬНО от модели. Сама модель не правится — она корректна для целей
// c/c-hal; под ПЛК адреса переопределяются здесь (приоритет: inline <
// address < внешняя карта).
//
// Класс локации (%I / %Q) генератор берёт из направления порта, поэтому
// входы и выходы нумеруются независимо. Для bit-порта адрес — номер БАЙТА,
// а бит — позиция в нём: 8 портов на байт.
//

// ── Входы → %IX ──
ElevatorMotor_SensorU = 0x0:0;
ElevatorMotor_SensorD = 0x0:1;
FloorButton_F1 = 0x0:2;
FloorButton_F2 = 0x0:3;
FloorButton_F3 = 0x0:4;
FloorButton_F4 = 0x0:5;
FloorButton_F5 = 0x0:6;
FloorButton_F6 = 0x0:7;
FloorButton_F7 = 0x1:0;
FloorButton_F8 = 0x1:1;
FloorButton_F9 = 0x1:2;
FloorSensor_F1_Top = 0x1:3;
FloorSensor_F1_Bottom = 0x1:4;
FloorSensor_F2_Top = 0x1:5;
FloorSensor_F2_Bottom = 0x1:6;
FloorSensor_F3_Top = 0x1:7;
FloorSensor_F3_Bottom = 0x2:0;
FloorSensor_F4_Top = 0x2:1;
FloorSensor_F4_Bottom = 0x2:2;
FloorSensor_F5_Top = 0x2:3;
FloorSensor_F5_Bottom = 0x2:4;
FloorSensor_F6_Top = 0x2:5;
FloorSensor_F6_Bottom = 0x2:6;
FloorSensor_F7_Top = 0x2:7;
FloorSensor_F7_Bottom = 0x3:0;
FloorSensor_F8_Top = 0x3:1;
FloorSensor_F8_Bottom = 0x3:2;
FloorSensor_F9_Top = 0x3:3;
FloorSensor_F9_Bottom = 0x3:4;
CabinButton_F1 = 0x3:5;
CabinButton_F2 = 0x3:6;
CabinButton_F3 = 0x3:7;
CabinButton_F4 = 0x4:0;
CabinButton_F5 = 0x4:1;
CabinButton_F6 = 0x4:2;
CabinButton_F7 = 0x4:3;
CabinButton_F8 = 0x4:4;
CabinButton_F9 = 0x4:5;
CabinButton_DO = 0x4:6;
CabinButton_DC = 0x4:7;

// ── Выходы → %QX ──
ElevatorMotor_Up = 0x0:0;
ElevatorMotor_Down = 0x0:1;
ElevatorMotor_Stop = 0x0:2;
DoorOpen = 0x0:3;

